# (regex do id sem prefixo s_) -> (plano, parâmetros). Primeira regra que casar vence.
DRAG = {'black': ('#3a3a46', '#6a6a7a', '#1a1a22'), 'blue': ('#2f6bd1', '#8ab4f0', '#183a7a'), 'brass': ('#c9a23a', '#ecd890', '#7a5a14'), 'bronze': ('#a8743a', '#d8b078', '#5a3a14'), 'copper': ('#b8602a', '#e0a070', '#5a2a10'), 'gold': ('#e0b43a', '#f6e090', '#8a6410'), 'green': ('#3f9a4b', '#a0d890', '#1a4a22'), 'red': ('#c0392b', '#f0b070', '#6a1810'), 'silver': ('#b8c0cc', '#eceff4', '#6a7280'), 'white': ('#dce8f0', '#ffffff', '#7a96aa')}
IDADE = {'wyrmling': 0.6, 'young': 0.78, 'adult': 0.95, 'ancient': 1.0}
def dragao_de(i):
    import re
    m = re.match(r'(adult|ancient|young)?_?(\w+?)_dragon(_wyrmling)?$', i)
    cor = next((c for c in DRAG if c in i), 'red'); idade = 'wyrmling' if 'wyrmling' in i else next((a for a in ('ancient', 'young', 'adult') if a in i), 'adult')
    c1, c2, c3 = DRAG[cor]; return ('dragao', dict(c1=c1, c2=c2, c3=c3, esc=IDADE[idade]))
